def gen(rng):
    def fmt(arrs):
        lines = [str(len(arrs))]
        for a in arrs:
            lines.append(str(len(a)) + (' ' + ' '.join(map(str, a)) if a else ''))
        return '\n'.join(lines)
    def rarr(m, lo, hi):
        return sorted(rng.randint(lo, hi) for _ in range(m))
    tests = [
        fmt([[5]]),
        fmt([[], [7], []]),
        fmt([[1, 1, 1], [1, 1], [1]]),
        fmt([[-5, -3, 0], [-4, -4, 9], [], [-10, 10]]),
        fmt([[1, 2, 3], [4, 5, 6], [7, 8, 9]]),
        fmt([[7, 8, 9], [4, 5, 6], [1, 2, 3]]),
        fmt([[-10**9, 10**9], [-10**9, 10**9]]),
    ]
    for _ in range(40):
        k = rng.randint(1, 6)
        while True:
            arrs = [rarr(rng.randint(0, 6), -10, 10) for _ in range(k)]
            if any(arrs):
                break
        tests.append(fmt(arrs))
    tests.append(fmt([rarr(100000, -10**9, 10**9)]))
    tests.append(fmt([rarr(10, -10**9, 10**9) for _ in range(10000)]))
    tests.append(fmt([rarr(rng.randint(0, 600), -10**9, 10**9) for _ in range(300)]))
    arrs = [rarr(rng.randint(0, 40), -1000, 1000) for _ in range(5000)]
    arrs[0] = arrs[0] or [0]
    tests.append(fmt(arrs))
    return tests
